ROUTE_OLD = (
    '    if (/^[0-8]$/.test(section || "")) {\n'
    '      const target = document.getElementById(section === "0" ? "standard-intro" : `standard-${section}`);'
)
ROUTE_NEW = (
    '    if (/^[0-9]$/.test(section || "")) {\n'
    '      const ids = { 0: "standard-intro", 9: "standard-industry" };\n'
    '      const target = document.getElementById(ids[section] || `standard-${section}`);'
)


def apply(html: str) -> str:
    """Применить правки к странице со свежесгенерированными разделами."""
    for old, new in PAIRS:
        found = html.count(old)
        if found != 1:
            raise SystemExit(f"issue_464/site_standards: ожидалось 1 совпадение, найдено {found}: {old[:80]}")
        html = html.replace(old, new)
    return html


def app_js_patches(patches: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """Патчи app.js порта: маршрут section=9 заменяет маршрут issue #423."""
    return [(old, ROUTE_NEW if new == ROUTE_OLD else new) for old, new in patches]
